SELECT ca.ca_state AS state, c.c_birth_month AS birth_month, COUNT(DISTINCT c.c_customer_sk) AS num_customers, AVG(c.c_current_hdemo_sk) AS avg_demo_sk, MAX(c.c_last_review_date) AS latest_review, (SELECT AVG(i_current_price) FROM item WHERE i_category = 'Sports') AS avg_sports_price FROM customer c JOIN customer_address ca ON c.c_current_addr_sk = ca.ca_address_sk WHERE ca.ca_country = 'United States' AND c.c_preferred_cust_flag = 'Y' AND c.c_birth_year BETWEEN 1970 AND 1990 GROUP BY ca.ca_state, c.c_birth_month HAVING COUNT(*) > 5 ORDER BY num_customers DESC, avg_sports_price ASC LIMIT 100
